/**
 * Generation of the per-invocation entry script.
 *
 * ExtendScript has no import mechanism worth relying on and no way to pass
 * arguments, so the driver hands the host its request and result paths through
 * a global. The generated file is deliberately small: the host script itself
 * is a static, versioned file, not something regenerated per command.
 *
 * The one thing the entry adds is a guard. An exception that escapes a script
 * run through `DoScriptFile` / `-r` — a syntax error in the host included — is
 * shown by AE as a modal alert, and AE then answers nothing until a person
 * dismisses it (observed on 26.5x89: the AppleEvent times out after 120 s). So
 * the entry catches whatever escapes the host and publishes it as a failure
 * envelope. It cannot use the host's codec, which may be what failed, so it
 * carries its own string quoting.
 */

import { writeFileSync } from "node:fs";
import { join } from "node:path";

/**
 * Quotes a value as an ES3 string literal. `JSON.stringify` handles the common
 * cases, but U+2028/U+2029 are legal in JSON and illegal in ES3 string
 * literals, so they are escaped explicitly.
 */
export function es3StringLiteral(value: string): string {
  return JSON.stringify(value)
    .replace(/\u2028/g, "\\u2028")
    .replace(/\u2029/g, "\\u2029");
}

/** Slash-free join: the host script builds its own paths with `/`. */
export function toPosixPath(value: string): string {
  return value.replace(/\\/g, "/");
}

/**
 * ES3 source for the guard's fallback: writes a failure envelope for `error`
 * to `__a8n.result` without `JSON` and without anything from the host.
 */
const PUBLISH_ESCAPED_ERROR = [
  "(function (error) {",
  "  function quote(text) {",
  '    var out = "\\"";',
  "    for (var i = 0; i < text.length; i++) {",
  "      var ch = text.charAt(i);",
  "      var code = text.charCodeAt(i);",
  '      if (ch === "\\"" || ch === "\\\\") {',
  '        out += "\\\\" + ch;',
  "      } else if (code < 32 || code === 0x2028 || code === 0x2029) {",
  "        var hex = code.toString(16);",
  '        out += "\\\\u" + "0000".substring(hex.length) + hex;',
  "      } else {",
  "        out += ch;",
  "      }",
  "    }",
  '    return out + "\\"";',
  "  }",
  '  var name = "Error";',
  '  var message = "unknown error";',
  "  var line = null;",
  "  try {",
  "    if (error !== null && typeof error === \"object\") {",
  "      if (error.name) { name = String(error.name); }",
  "      message = error.message !== undefined ? String(error.message) : String(error);",
  "      if (typeof error.line === \"number\") { line = error.line; }",
  "    } else {",
  "      message = String(error);",
  "    }",
  "  } catch (ignored) {",
  "    // Keep the defaults; reporting something beats reporting nothing.",
  "  }",
  "  var text = __a8n.failurePrefix +",
  '    "{\\"name\\":" + quote(name) +',
  '    ",\\"message\\":" + quote("host script raised past its own handler: " + message) +',
  '    (line === null ? "" : ",\\"line\\":" + line) + "}}";',
  "  var file = new File(__a8n.result);",
  '  file.encoding = "UTF-8";',
  '  if (file.open("w")) {',
  "    file.write(text);",
  "    file.close();",
  "  }",
  "})",
].join("\n");

export function writeBootstrapScript(options: {
  entryPath: string;
  hostScriptPath: string;
  requestPath: string;
  resultPath: string;
  /** The request id, so a failure the host could not report still answers it. */
  id: string;
}): string {
  // Everything up to the error payload is known now; only the error is not.
  const failurePrefix = `{"v":1,"id":${JSON.stringify(options.id)},"ok":false,"durationMs":0,"error":`;
  const source = [
    "// Generated by @ido-bata/ae-a8n. Do not edit; regenerate per invocation.",
    "var __a8n = {",
    `  request: ${es3StringLiteral(toPosixPath(options.requestPath))},`,
    `  result: ${es3StringLiteral(toPosixPath(options.resultPath))},`,
    `  failurePrefix: ${es3StringLiteral(failurePrefix)}`,
    "};",
    "try {",
    `  $.evalFile(new File(${es3StringLiteral(toPosixPath(options.hostScriptPath))}));`,
    "} catch (__a8nEscaped) {",
    "  try {",
    `    ${PUBLISH_ESCAPED_ERROR.split("\n").join("\n    ")}(__a8nEscaped);`,
    "  } catch (__a8nIgnored) {",
    "    // Nothing left to report with. Swallowing it still keeps AE free of a",
    "    // modal alert; the driver times out with the request unanswered.",
    "  }",
    "}",
    "",
  ].join("\n");

  writeFileSync(options.entryPath, source, "utf-8");
  return options.entryPath;
}

export function entryScriptPath(sessionRoot: string, id: string): string {
  return join(sessionRoot, "staging", `${id}.entry.jsx`);
}
